package pl.forma.todo;
import android.app.*;import android.content.*;import android.os.*;import android.net.Uri;import org.json.*;
public class Reminder extends BroadcastReceiver {
 static PendingIntent pi(Context c,String id,String title){Intent i=new Intent(c,Reminder.class).setData(Uri.parse("forma://alarm/"+id)).putExtra("id",id).putExtra("title",title);return PendingIntent.getBroadcast(c,0,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static void set(Context c,String id,String title,long time){AlarmManager a=c.getSystemService(AlarmManager.class);PendingIntent p=pi(c,id,title);if(Build.VERSION.SDK_INT<31||a.canScheduleExactAlarms())a.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,time,p);else a.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,time,p);try{JSONObject j=new JSONObject();j.put("title",title);j.put("time",time);c.getSharedPreferences("alarms",0).edit().putString(id,j.toString()).apply();}catch(Exception e){}}
 static void cancel(Context c,String id){c.getSystemService(AlarmManager.class).cancel(pi(c,id,""));c.getSharedPreferences("alarms",0).edit().remove(id).apply();}
 public void onReceive(Context c,Intent i){String id=i.getStringExtra("id");c.getSharedPreferences("alarms",0).edit().remove(id).apply();NotificationManager n=c.getSystemService(NotificationManager.class);n.createNotificationChannel(new NotificationChannel("tasks","Przypomnienia",NotificationManager.IMPORTANCE_HIGH));PendingIntent p=PendingIntent.getActivity(c,0,new Intent(c,MainActivity.class),PendingIntent.FLAG_IMMUTABLE);n.notify(id,1,new Notification.Builder(c,"tasks").setSmallIcon(android.R.drawable.ic_popup_reminder).setContentTitle(i.getStringExtra("title")).setContentText("Przypomnienie FORMA").setContentIntent(p).setAutoCancel(true).build());}
}
